FINANCIAL_OCCUPATIONS = {
    "retail": ["teacher", "nurse", "sales associate"],
    "institutional": ["portfolio manager", "quantitative analyst", "hedge fund"],
    "insider": ["cfo", "vp finance", "corporate treasurer"],
}

def infer_participant_type(occupation: str) -> str:
    occ_lower = occupation.lower()
    for archetype, keywords in FINANCIAL_OCCUPATIONS.items():
        if any(k in occ_lower for k in keywords):
            return archetype
    return "retail"  # default

